{"source":"import React from "react";
import {
  AbsoluteFill,
  Sequence,
  interpolate,
  spring,
  useCurrentFrame,
} from "remotion";
import { palette } from "./contract";

const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

const baseText: React.CSSProperties = {
  color: palette.foreground,
  fontFamily: "Archivo",
  margin: 0,
};

const Mark: React.FC<{ size?: number }> = ({ size = 34 }) => (
  <div
    style={{
      width: size,
      height: size,
      borderRadius: Math.round(size * 0.28),
      background: palette.accent,
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      gap: Math.max(3, size * 0.1),
      padding: size * 0.22,
      boxSizing: "border-box",
      flexShrink: 0,
    }}
  >
    <div style={{ height: Math.max(2, size * 0.075), width: "100%", borderRadius: 10, background: palette.background }} />
    <div style={{ height: Math.max(2, size * 0.075), width: "68%", borderRadius: 10, background: palette.background }} />
  </div>
);

const Backdrop: React.FC = () => (
  <AbsoluteFill
    style={{
      backgroundColor: palette.background,
      backgroundImage:
        "radial-gradient(ellipse at 76% 42%, rgba(120,185,237,0.10), transparent 38%), radial-gradient(ellipse at 18% 84%, rgba(184,243,107,0.08), transparent 36%), linear-gradient(rgba(245,245,242,0.025) 1px, transparent 1px), linear-gradient(90deg, rgba(245,245,242,0.025) 1px, transparent 1px)",
      backgroundSize: "auto, auto, 72px 72px, 72px 72px",
    }}
  />
);

const IntroArt: React.FC<{ frame: number }> = ({ frame }) => {
  const enter = spring({ frame: Math.max(0, frame - 8), fps: 30, config: { damping: 20, stiffness: 90 } });
  const drift = interpolate(frame, [0, 90], [12, -6], clamp);
  return (
    <div
      style={{
        position: "absolute",
        right: 165,
        top: 210,
        width: 660,
        height: 610,
        opacity: enter,
        transform: `translate3d(0,${(1 - enter) * 46 + drift}px,0) rotate(${interpolate(frame, [0, 90], [1.4, 0], clamp)}deg)`,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 24,
          borderRadius: 36,
          background: "rgba(120,185,237,0.08)",
          filter: "blur(36px)",
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: 30,
          borderRadius: 30,
          border: "1px solid rgba(245,245,242,0.13)",
          background: "rgba(24,26,30,0.94)",
          boxShadow: "0 34px 100px rgba(0,0,0,0.36)",
          boxSizing: "border-box",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "1px 4px 24px" }}>
          <div style={{ ...baseText, fontSize: 21, fontWeight: 650 }}>Your week</div>
          <div style={{ display: "flex", gap: 8 }}>
            {[palette.accent, palette.secondary, "rgba(245,245,242,0.25)"].map((color, i) => (
              <div key={i} style={{ width: 10, height: 10, borderRadius: 99, background: color }} />
            ))}
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 10, marginBottom: 17 }}>
          {["MON", "TUE", "WED", "THU", "FRI"].map((day, i) => (
            <div key={day} style={{ textAlign: "center", padding: "12px 0", borderRadius: 12, background: i === 1 ? "rgba(184,243,107,0.12)" : "rgba(245,245,242,0.035)" }}>
              <div style={{ ...baseText, color: i === 1 ? palette.accent : palette.muted, fontSize: 12, letterSpacing: 1.1, fontWeight: 650 }}>{day}</div>
              <div style={{ ...baseText, fontSize: 19, fontWeight: 600, marginTop: 7 }}>{12 + i}</div>
            </div>
          ))}
        </div>
        <div style={{ display: "grid", gap: 12 }}>
          {[
            { label: "Design review", time: "10:00", color: palette.secondary, width: "78%" },
            { label: "Focus block", time: "11:30", color: palette.accent, width: "91%" },
            { label: "Team sync", time: "14:00", color: palette.secondary, width: "66%" },
            { label: "Weekly review", time: "15:30", color: palette.accent, width: "83%" },
          ].map((item, i) => (
            <div key={item.label} style={{ height: 76, borderRadius: 15, border: "1px solid rgba(245,245,242,0.075)", background: "rgba(245,245,242,0.025)", display: "flex", alignItems: "center", padding: "0 18px", gap: 16 }}>
              <div style={{ ...baseText, color: palette.muted, fontSize: 13, width: 48 }}>{item.time}</div>
              <div style={{ width: item.width, height: 46, borderRadius: 11, background: `${item.color}20`, borderLeft: `3px solid ${item.color}`, display: "flex", alignItems: "center", paddingLeft: 14, boxSizing: "border-box" }}>
                <span style={{ ...baseText, fontSize: 16, fontWeight: 600 }}>{item.label}</span>
              </div>
              <div style={{ display: "flex", marginLeft: "auto", paddingRight: 3 }}>
                {[0, 1].map((n) => <div key={n} style={{ width: 24, height: 24, borderRadius: 20, marginLeft: n ? -6 : 0, background: n ? "rgba(120,185,237,0.8)" : "rgba(184,243,107,0.8)", border: "2px solid #181a1e" }} />)}
              </div>
            </div>
          ))}
        </div>
      </div>
      <div style={{ position: "absolute", right: -28, bottom: 52, width: 128, height: 128, borderRadius: 28, background: palette.accent, color: palette.background, display: "grid", placeItems: "center", transform: `rotate(${interpolate(frame, [0, 90], [-7, 4], clamp)}deg)`, boxShadow: "0 18px 52px rgba(184,243,107,0.18)" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontFamily: "Archivo", fontSize: 38, lineHeight: 1, fontWeight: 700 }}>↗</div>
          <div style={{ fontFamily: "Archivo", fontSize: 13, marginTop: 7, fontWeight: 650 }}>Your plan</div>
        </div>
      </div>
    </div>
  );
};

const Intro: React.FC = () => {
  const frame = useCurrentFrame();
  const fade = interpolate(frame, [0, 8, 82, 96], [0, 1, 1, 0], clamp);
  const titleIn = spring({ frame: Math.max(0, frame - 5), fps: 30, config: { damping: 21, stiffness: 95 } });
  return (
    <AbsoluteFill style={{ opacity: fade }}>
      <div style={{ position: "absolute", left: 150, top: 106, display: "flex", alignItems: "center", gap: 15 }}>
        <Mark size={43} />
        <span style={{ ...baseText, fontSize: 30, fontWeight: 700, letterSpacing: -0.7 }}>Relay</span>
      </div>
      <div style={{ position: "absolute", left: 150, top: 344, width: 850, opacity: titleIn, transform: `translateY(${(1 - titleIn) * 28}px)` }}>
        <h1 style={{ ...baseText, fontSize: 82, lineHeight: 1.08, letterSpacing: -4.2, fontWeight: 680 }}>
          Make room for<br />focused work
        </h1>
        <div style={{ marginTop: 38, height: 5, width: 124, borderRadius: 8, background: palette.accent, transform: `scaleX(${interpolate(frame, [16, 35], [0.12, 1], clamp)})`, transformOrigin: "left" }} />
      </div>
      <IntroArt frame={frame} />
      <div style={{ position: "absolute", left: 150, bottom: 92, width: 490, height: 1, background: "rgba(245,245,242,0.13)" }} />
      <div style={{ position: "absolute", left: 150, bottom: 78, width: 122, height: 3, borderRadius: 4, background: palette.accent }} />
    </AbsoluteFill>
  );
};

const Avatar: React.FC<{ label: string; color: string; size?: number }> = ({ label, color, size = 30 }) => (
  <div style={{ width: size, height: size, borderRadius: 99, background: color, color: palette.background, fontFamily: "Archivo", fontSize: size * 0.36, fontWeight: 700, display: "grid", placeItems: "center", border: "2px solid #191b1f", boxSizing: "border-box" }}>{label}</div>
);

const TaskCard: React.FC<{ label: string; color: string; delay: number; frame: number; people?: string }> = ({ label, color, delay, frame, people = "AL" }) => {
  const entry = spring({ frame: Math.max(0, frame - delay), fps: 30, config: { damping: 19, stiffness: 115 } });
  return (
    <div style={{ opacity: entry, transform: `translateY(${(1 - entry) * 14}px)`, minHeight: 74, borderRadius: 12, padding: "12px 10px 10px", background: `${color}14`, border: "1px solid ${color}28`, borderLeft: `3px solid ${color}`, boxSizing: "border-box" }}>
      <div style={{ ...baseText, fontSize: 13, lineHeight: 1.25, fontWeight: 600 }}>{label}</div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 11 }}>
        <div style={{ width: 29, height: 3, borderRadius: 4, background: color, opacity: 0.8 }} />
        <Avatar label={people} color={color} size={22} />
      </div>
    </div>
  );
};

const Product: React.FC = () => {
  const frame = useCurrentFrame();
  const fade = interpolate(frame, [0, 13, 177, 192], [0, 1, 1, 0], clamp);
  const entry = spring({ frame: Math.max(0, frame - 2), fps: 30, config: { damping: 22, stiffness: 100 } });
  const days = [
    { day: "MON", date: "12", tasks: [{ label: "Draft brief", color: palette.accent, people: "AL" }, { label: "Team sync", color: palette.secondary, people: "JM" }] },
    { day: "TUE", date: "13", tasks: [{ label: "Design review", color: palette.secondary, people: "SK" }, { label: "Focus block", color: palette.accent, people: "AL" }] },
    { day: "WED", date: "14", tasks: [{ label: "Project notes", color: palette.accent, people: "JM" }, { label: "Team sync", color: palette.secondary, people: "SK" }] },
    { day: "THU", date: "15", tasks: [{ label: "Review plan", color: palette.secondary, people: "AL" }, { label: "Focus block", color: palette.accent, people: "JM" }] },
    { day: "FRI", date: "16", tasks: [{ label: "Weekly review", color: palette.accent, people: "SK" }, { label: "Wrap up", color: palette.secondary, people: "AL" }] },
  ];
  return (
    <AbsoluteFill style={{ opacity: fade }}>
      <div style={{ position: "absolute", left: 125, right: 125, top: 94, bottom: 76, borderRadius: 27, overflow: "hidden", border: "1px solid rgba(245,245,242,0.14)", background: "rgba(23,25,29,0.97)", boxShadow: "0 30px 100px rgba(0,0,0,0.35)", opacity: entry, transform: `translateY(${(1 - entry) * 24}px) scale(${0.985 + entry * 0.015})` }}>
        <div style={{ height: 73, borderBottom: "1px solid rgba(245,245,242,0.09)", display: "flex", alignItems: "center", padding: "0 27px", gap: 13, boxSizing: "border-box" }}>
          <Mark size={34} />
          <span style={{ ...baseText, fontSize: 21, fontWeight: 700 }}>Relay</span>
          <div style={{ height: 24, width: 1, background: "rgba(245,245,242,0.13)", margin: "0 5px" }} />
          <span style={{ ...baseText, color: palette.muted, fontSize: 15 }}>Team workspace</span>
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ display: "flex" }}>
              <div style={{ marginLeft: 0 }}><Avatar label="AL" color={palette.accent} /></div>
              <div style={{ marginLeft: -8 }}><Avatar label="JM" color={palette.secondary} /></div>
              <div style={{ marginLeft: -8 }}><Avatar label="SK" color="#D6B5EA" /></div>
            </div>
            <div style={{ borderRadius: 9, border: "1px solid rgba(245,245,242,0.13)", padding: "8px 13px", color: palette.foreground, fontFamily: "Archivo", fontSize: 13 }}>Share week</div>
          </div>
        </div>
        <div style={{ display: "flex", height: "calc(100% - 73px)" }}>
          <div style={{ width: 214, flexShrink: 0, borderRight: "1px solid rgba(245,245,242,0.08)", padding: "25px 15px", boxSizing: "border-box" }}>
            <div style={{ ...baseText, color: palette.muted, fontSize: 11, fontWeight: 650, letterSpacing: 1.3, padding: "0 12px", marginBottom: 13 }}>WORKSPACE</div>
            {[
              { name: "My week", mark: "▦", active: true },
              { name: "Team board", mark: "◫", active: false },
              { name: "Focus", mark: "◉", active: false },
            ].map((item) => (
              <div key={item.name} style={{ height: 43, display: "flex", alignItems: "center", gap: 12, padding: "0 12px", borderRadius: 9, background: item.active ? "rgba(184,243,107,0.11)" : "transparent", marginBottom: 4 }}>
                <span style={{ color: item.active ? palette.accent : palette.muted, fontFamily: "Archivo", fontSize: 17, width: 18 }}>{item.mark}</span>
                <span style={{ ...baseText, color: item.active ? palette.foreground : palette.muted, fontSize: 14, fontWeight: item.active ? 650 : 450 }}>{item.name}</span>
              </div>
            ))}
            <div style={{ height: 1, background: "rgba(245,245,242,0.09)", margin: "19px 8px" }} />
            <div style={{ ...baseText, color: palette.muted, fontSize: 11, fontWeight: 650, letterSpacing: 1.3, padding: "0 12px", marginBottom: 14 }}>YOUR TEAM</div>
            {[
              ["Design", palette.secondary],
              ["Product", palette.accent],
              ["Operations", "#D6B5EA"],
            ].map(([name, color]) => (
              <div key={name as string} style={{ height: 39, display: "flex", alignItems: "center", gap: 11, padding: "0 12px" }}>
                <div style={{ width: 8, height: 8, borderRadius: 99, background: color as string }} />
                <span style={{ ...baseText, color: palette.muted, fontSize: 13 }}>{name}</span>
              </div>
            ))}
          </div>
          <div style={{ flex: 1, minWidth: 0, padding: "28px 23px 22px", boxSizing: "border-box" }}>
            <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", marginBottom: 23 }}>
              <div>
                <div style={{ ...baseText, color: palette.muted, fontSize: 11, fontWeight: 650, letterSpacing: 1.6, marginBottom: 7 }}>WEEKLY PLAN</div>
                <h2 style={{ ...baseText, fontSize: 38, lineHeight: 1.05, letterSpacing: -1.5, fontWeight: 680 }}>Plan together</h2>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 9, padding: "9px 12px", border: "1px solid rgba(245,245,242,0.12)", borderRadius: 9, color: palette.muted, fontFamily: "Archivo", fontSize: 13 }}>← <span style={{ color: palette.foreground, margin: "0 7px" }}>May 12 – 16</span> →</div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(5, minmax(0, 1fr))", gap: 10, height: "calc(100% - 85px)" }}>
              {days.map((day, i) => (
                <div key={day.day} style={{ minWidth: 0, borderRadius: 12, background: "rgba(245,245,242,0.025)", border: "1px solid rgba(245,245,242,0.07)", padding: "13px 9px", boxSizing: "border-box" }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", margin: "0 2px 14px" }}>
                    <span style={{ ...baseText, color: palette.muted, fontSize: 11, fontWeight: 650, letterSpacing: 0.6 }}>{day.day}</span>
                    <span style={{ ...baseText, fontSize: 13, fontWeight: 650, color: i === 1 ? palette.accent : palette.foreground }}>{day.date}</span>
                  </div>
                  <div style={{ display: "grid", gap: 9 }}>
                    {day.tasks.map((task, j) => <TaskCard key={task.label + j} label={task.label} color={task.color} people={task.people} delay={10 + i * 4 + j * 5} frame={frame} />)}
                    {i === 2 && <div style={{ height: 48, borderRadius: 11, border: "1px dashed rgba(245,245,242,0.16)", display: "grid", placeItems: "center", color: palette.muted, fontFamily: "Archivo", fontSize: 12 }}>+ Add plan</div>}
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div style={{ width: 355, flexShrink: 0, borderLeft: "1px solid rgba(245,245,242,0.08)", padding: "27px 21px", boxSizing: "border-box", display: "flex", flexDirection: "column", gap: 17 }}>
            <div style={{ borderRadius: 15, padding: "20px 19px 18px", background: "rgba(120,185,237,0.09)", border: "1px solid rgba(120,185,237,0.19)", opacity: interpolate(frame, [18, 34], [0, 1], clamp), transform: `translateY(${interpolate(frame, [18, 34], [14, 0], clamp)}px)` }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 19 }}>
                <span style={{ ...baseText, fontSize: 20, lineHeight: 1.15, letterSpacing: -0.4, fontWeight: 650, maxWidth: 230 }}>Protect focus time</span>
                <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(120,185,237,0.16)", display: "grid", placeItems: "center", color: palette.secondary, fontFamily: "Archivo", fontSize: 18 }}>◌</div>
              </div>
              <div style={{ height: 1, background: "rgba(245,245,242,0.11)", marginBottom: 16 }} />
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ width: 44, height: 44, borderRadius: 13, background: "rgba(120,185,237,0.17)", display: "grid", placeItems: "center", color: palette.secondary, fontFamily: "Archivo", fontSize: 20 }}>◷</div>
                <div>
                  <div style={{ ...baseText, fontSize: 14, fontWeight: 600 }}>Focus block</div>
                  <div style={{ ...baseText, color: palette.muted, fontSize: 12, marginTop: 4 }}>9:00 – 11:00</div>
                </div>
              </div>
              <div style={{ height: 5, borderRadius: 9, background: "rgba(245,245,242,0.10)", marginTop: 17, overflow: "hidden" }}>
                <div style={{ width: `${interpolate(frame, [28, 78], [4, 73], clamp)}%`, height: "100%", borderRadius: 9, background: palette.secondary }} />
              </div>
            </div>
            <div style={{ flex: 1, minHeight: 250, borderRadius: 15, padding: "20px 19px", background: "rgba(245,245,242,0.035)", border: "1px solid rgba(245,245,242,0.08)", opacity: interpolate(frame, [35, 52], [0, 1], clamp), transform: `translateY(${interpolate(frame, [35, 52], [14, 0], clamp)}px)` }}>
              <div style={{ ...baseText, fontSize: 20, letterSpacing: -0.4, fontWeight: 650 }}>See progress</div>
              <div style={{ display: "flex", alignItems: "center", gap: 18, marginTop: 23 }}>
                <div style={{ width: 93, height: 93, borderRadius: 99, background: `conic-gradient(${palette.accent} ${interpolate(frame, [48, 92], [5, 76], clamp)}%, rgba(245,245,242,0.10) 0)`, display: "grid", placeItems: "center", flexShrink: 0 }}>
                  <div style={{ width: 68, height: 68, borderRadius: 99, background: "#1b1d21", display: "grid", placeItems: "center", color: palette.foreground, fontFamily: "Archivo", fontSize: 13, fontWeight: 650 }}>WEEK</div>
                </div>
                <div style={{ flex: 1, display: "grid", gap: 10 }}>
                  {[palette.accent, palette.secondary, "rgba(245,245,242,0.48)"].map((color, i) => (
                    <div key={i} style={{ height: 7, borderRadius: 8, background: "rgba(245,245,242,0.08)", overflow: "hidden" }}>
                      <div style={{ height: "100%", width: `${interpolate(frame, [48 + i * 5, 100 + i * 5], [8, [82, 61, 45][i]], clamp)}%`, borderRadius: 8, background: color }} />
                    </div>
                  ))}
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "flex-end", gap: 9, height: 72, marginTop: 24 }}>
                {[38, 60, 45, 83, 66, 93, 72].map((height, i) => (
                  <div key={i} style={{ flex: 1, height: `${height}%`, borderRadius: 5, background: i === 5 ? palette.accent : i % 2 ? "rgba(120,185,237,0.65)" : "rgba(245,245,242,0.18)", transform: `scaleY(${interpolate(frame, [55 + i * 3, 78 + i * 3], [0.08, 1], clamp)})`, transformOrigin: "bottom" }} />
                ))}
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: 9, color: palette.muted, fontFamily: "Archivo", fontSize: 10, letterSpacing: 0.4 }}><span>MON</span><span>TUE</span><span>WED</span><span>THU</span><span>FRI</span></div>
            </div>
          </div>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 31, textAlign: "center", color: "rgba(245,245,242,0.48)", fontFamily: "Archivo", fontSize: 12, letterSpacing: 1.5 }}>A SHARED WEEK, AT A GLANCE</div>
    </AbsoluteFill>
  );
};

const Closing: React.FC = () => {
  const frame = useCurrentFrame();
  const enter = spring({ frame: Math.max(0, frame - 1), fps: 30, config: { damping: 22, stiffness: 85 } });
  const opacity = interpolate(frame, [0, 15], [0, 1], clamp);
  return (
    <AbsoluteFill style={{ opacity }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 273, display: "flex", flexDirection: "column", alignItems: "center", opacity: enter, transform: `translateY(${(1 - enter) * 26}px) scale(${0.985 + enter * 0.015})` }}>
        <Mark size={55} />
        <h1 style={{ ...baseText, fontSize: 76, lineHeight: 1.12, letterSpacing: -3.5, fontWeight: 680, textAlign: "center", marginTop: 30, maxWidth: 1500 }}>
          Start your next week<br />with <span style={{ color: palette.accent }}>Relay</span>
        </h1>
        <div style={{ marginTop: 37, width: 78, height: 4, borderRadius: 6, background: palette.accent, transform: `scaleX(${interpolate(frame, [12, 28], [0.2, 1], clamp)})` }} />
      </div>
      <div style={{ position: "absolute", left: 150, right: 150, bottom: 90, height: 1, background: "rgba(245,245,242,0.12)" }} />
      <div style={{ position: "absolute", left: 150, bottom: 67, display: "flex", alignItems: "center", gap: 10 }}>
        <Mark size={24} />
        <span style={{ ...baseText, fontSize: 16, fontWeight: 650, letterSpacing: 0.2 }}>Relay</span>
      </div>
    </AbsoluteFill>
  );
};

export const BenchmarkVideo: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: palette.background, fontFamily: "Archivo" }}>
    <Backdrop />
    <Sequence from={0} durationInFrames={96}>
      <Intro />
    </Sequence>
    <Sequence from={84} durationInFrames={192}>
      <Product />
    </Sequence>
    <Sequence from={264} durationInFrames={96}>
      <Closing />
    </Sequence>
  </AbsoluteFill>
);
"}
